func cmdCloseoutCheck(root string, args []string, stdout, stderr io.Writer) int {
	ref, jsonOutput, ok := parseScopeCheckArgs("closeout-check", args, stderr)
	if !ok {
		return 2
	}
	store, localRef, err := cliReviewStore(root, ref)
	if err != nil {
		render(io.Discard, stderr).Failure("pose closeout-check: " + err.Error())
		return 1
	}
	root, ref = store.Root, localRef
	state, err := cliCloseoutStateForStore(store, ref)
	if err != nil {
		fmt.Fprintf(stderr, "pose closeout-check: %v\n", err)
		return 1
	}
	if jsonOutput {
		if code := writeJSON(stdout, state); code != 0 {
			return code
		}
		if !state.Terminal {
			return 1
		}
		return 0
	}
	fmt.Fprintf(stdout, "closeout.scope=%s\ncloseout.digest=%s\ncloseout.lifecycle_done=%t\ncloseout.review_approved=%t\ncloseout.terminal=%t\ncloseout.next_action=%s\n", state.Scope, state.ScopeDigest, state.LifecycleDone, state.Review.Approved, state.Terminal, state.NextAction)
	if state.Review.Assurance != nil {
		render(stdout, stderr).Field("closeout.review_assurance", posemodel.RenderReviewAssurance(*state.Review.Assurance))
	}
	for _, blocker := range state.Blockers {
		fmt.Fprintf(stderr, "[ERROR] %s\n", blocker)
	}
	if !state.Terminal {
		return 1
	}
	return 0
}

func cliCloseoutState(root, ref string) (posemodel.CloseoutState, error) {
	return cliCloseoutStateIn(root, ref, posemodel.NativeFiles())
}

func cliCloseoutStateIn(root, ref string, files posemodel.Files) (posemodel.CloseoutState, error) {
	files = posemodel.FilesOrNative(files)
	resolver, project, err := posemodel.EnvironmentArtifactResolverIn(files, root, "")
	if err != nil {
		return posemodel.CloseoutState{}, fmt.Errorf("invalid project configuration")
	}
	store := posemodel.Store{Root: root, FS: files, FederatedProjectID: project, FederatedResolver: &resolver}
	return cliCloseoutStateForStore(store, ref)
}

// cliCloseoutStateForStore evaluates through the selected Store binding. A
// guarded close must keep its project resolver and guarded root overlay; only
// the root-only compatibility helper above reconstructs a CLI resolver.
func cliCloseoutStateForStore(store posemodel.Store, ref string) (posemodel.CloseoutState, error) {
	scope, err := posemodel.ParseScopeRef(ref)
	if err != nil {
		return posemodel.CloseoutState{}, err
	}
	if scope.Kind != "roadmap" && scope.Kind != "milestone" {
		return store.GetCloseoutState(ref)
	}
	project := store.FederatedProjectID
	if project == "" {
		project, err = store.WriteProjectID()
		if err != nil {
			return posemodel.CloseoutState{}, fmt.Errorf("invalid project configuration")
		}
	}
	resolver := store.FederatedResolver
	if resolver == nil {
		value, _, resolverErr := posemodel.EnvironmentArtifactResolverIn(store.FS, store.Root, "")
		if resolverErr != nil {
			return posemodel.CloseoutState{}, fmt.Errorf("invalid project configuration")
		}
		resolver = &value
	}
	return store.GetCloseoutStateWithFederatedAcceptance(ref, project, *resolver)
}

func parseScopeCheckArgs(command string, args []string, stderr io.Writer) (string, bool, bool) {
	jsonFlag := " [--json]"
	if command == "close" {
		jsonFlag = ""
	}
	jsonOutput := false
	ref := ""
	for _, arg := range args {
		switch arg {
		case "--json":
			jsonOutput = true
		default:
			if strings.HasPrefix(arg, "-") || ref != "" {
				fmt.Fprintf(stderr, "Usage: pose %s <spec:slug|milestone:roadmap/id|roadmap:slug>%s\n", command, jsonFlag)
				return "", false, false
			}
			ref = arg
		}
	}
	if ref == "" {
		fmt.Fprintf(stderr, "Usage: pose %s <spec:slug|milestone:roadmap/id|roadmap:slug>%s\n", command, jsonFlag)
		return "", false, false

}

func cmdArtifactCheck(root string, args []string, stdout, stderr io.Writer) int {
	var spec, from, to string
	strict, jsonOutput := true, false
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--spec", "--from", "--to":
			if i+1 >= len(args) {
				return usageError(stderr, "Usage: pose artifact-check --spec <slug> [--from rev --to rev] [--strict|--tolerant] [--json]")
			}
			i++
			switch args[i-1] {
			case "--spec":
				spec = args[i]
			case "--from":
				from = args[i]
			case "--to":
				to = args[i]
			}
		case "--strict":
			strict = true
		case "--tolerant":
			strict = false
		case "--json":
			jsonOutput = true
		default:
			return usageError(stderr, "Usage: pose artifact-check --spec <slug> [--from rev --to rev] [--strict|--tolerant] [--json]")
		}
	}
	store := posemodel.Store{Root: root}
	full, err := store.GetSpec(spec)
	if err != nil {
		fmt.Fprintf(stderr, "pose artifact-check: %v\n", err)
		return 1
	}
	policy, err := posemodel.LoadArtifactPolicy(root)
	if err != nil {
		fmt.Fprintf(stderr, "pose artifact-check: %v\n", err)
		return 1
	}
	claims, found, err := posemodel.ParseArtifactClaims(*full, policy)
	if err != nil || !found || len(claims) == 0 {
		fmt.Fprintf(stderr, "pose artifact-check: spec %s has no valid artifact declaration: %v\n", spec, err)
		return 1
	}
	var sets []posemodel.ChangeSet
	if from != "" || to != "" {
		set, err := resolveGitChangeSet(root, spec, from, to)
		if err != nil {
			fmt.Fprintf(stderr, "pose artifact-check: %v\n", err)
			return 1
		}
		sets = append(sets, set)
	} else {
		for _, recorded := range loadRecordedChangeSets(root) {
			if recorded.Spec == spec {
				sets = append(sets, recorded)
			}
		}
		if set, err := resolveGitChangeSet(root, spec, "", ""); err == nil {
			alreadyPresent := false
			for _, existing := range sets {
				if existing.ID == set.ID {
					alreadyPresent = true
					break
				}
			}
			if !alreadyPresent {
				sets = append(sets, set)
			}
		}
		if len(sets) == 0 {
			fmt.Fprintf(stderr, "pose artifact-check: no commits carry POSE-Spec: %s\n", spec)
			return 1
		}
	}
	set := sets[0]
	tracked, err := gitTrackedPaths(root)
	if err != nil {
		fmt.Fprintf(stderr, "pose artifact-check: %v\n", err)
		return 1
	}
	// A later removal by another spec is read from every spec's claims and
	// change sets (spec pose-delivery-later-removal R4).
	var removals []posemodel.ArtifactRemoval
	if _, allClaims, allSets, _, _, gaps, err := collectArtifactGraphInputsWithGapsIn(posemodel.NativeFiles(), root); err == nil {
		removals = artifactRemovals(root, allClaims, allSets, tracked, gaps, sets...)
	}
