		t.Fatal(err)
	}
	ts := httptest.NewServer(New(pose.Store{Root: root}).Handler("", ""))
	defer ts.Close()
	diverged := func() []any {
		_, out := post(t, ts, `{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"pose_list_specs","arguments":{"limit":2}}}`)
		sc, _ := out.Result["structuredContent"].(map[string]any)
